// ── 4.3 Deploy / update inputs ──────────────────────────────────────────────
/// Body of POST /api/deploy. Mirrors the Node `o` object exactly.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]

/// Body of PATCH /api/workloads/:ns/:name (update). All optional.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]

/// Body of PUT /api/workloads/:ns/:name/domain
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]

/// Server-side sandbox list controls. `active=true` includes running/new
/// sandboxes; `active=false` includes suspended or terminating sandboxes.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(default, rename_all = "camelCase")]

/// PUT /api/settings body — all fields optional; only provided ones are applied.
/// An empty `dns_api_key` leaves the stored key unchanged; send "-" to clear it.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]

/// POST /api/sandboxes/provision — auto-provision a full sandbox: project-scoped
/// data engines + the selected platform services + the user's app, with domains.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]

/// Shared resource envelope for a sandbox. CPU and RAM are divided across its
/// workloads; persistent storage is assigned explicitly by workload role.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]

/// Direct project Identity selection. `source_project = None` restores the
/// sandbox's retained local IDP.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]

/// POST /api/infra body (deploy form)
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]

/// POST /api/builds body
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]

/// POST /api/webhooks/git body (git host push payload subset; parsed leniently)
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]

/// PUT /api/git-credentials body. `username` optional (defaults x-access-token).
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]

/// PUT /api/registries body — the full desired registry list.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase")]

// ── Cleanup tasks ───────────────────────────────────────────────────────────
/// POST /api/cleanup body.
#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
